// === Tab: Particle ===
//this is a simple particle object with 3 methods.
//each particles position,speed and acceleration is determined through pVectors.
//the 3 methods include: a display function, a random movement function and a gravity effect function.
//each particle is removed ffrom the sketch when it reaches a certain lifeSpan.
class Particle {
	constructor(x, y) {
		this.pos = createVector(x, y);
		this.speed = createVector(random(-2, 2), -10);
		this.acceleration = createVector(0, 3);
		this.lifeSpan = 0;
	}
	//displays each particle as a growing circle.
	displayCircles() {
		fill(0, 50);
		strokeWeight(1);
		//checking if color is active (colorButton.)
		if (colorActive){
			//using map to lerp through colorspace.
			stroke(map(this.lifeSpan,0,20,colorSlider.value(),colorSlider.value()+90),100,map(this.lifeSpan,0,20,100,20));
		}else{stroke(0,0,map(this.lifeSpan,0,20,100,20));//white circle.
				 }
		ellipse(this.pos.x, this.pos.y, this.lifeSpan * sizeSlider.value(), this.lifeSpan * sizeSlider.value());
		//adding to life spane each time a particle is displayed.
		this.lifeSpan++;
	}
	//moving the particles on a 2d noise plane.
	moveRandom() {
		let scale =75;
		this.pos.y += map(noise(this.pos.x / scale, this.pos.y / scale), 0, 1, -1, 1) * 10;
		this.pos.x += map(noise(this.pos.x / scale + 10000, this.pos.y / scale), 0, 1, -1, 1) * 10;
	}
	//ccorresponds to gravity effect.
	moveDown() {
		this.pos.add(this.speed);
		this.speed.add(this.acceleration);
	}
}

