//This is a p5js sketch that uses computer vision to generate particles.
//Open Cv .js labrary is used to determine id an object in the camera frame is moving.
//If movement is detected then particles are generated and will stay on the canvas for a certain lifeSpan.
//user can control how particles move and how they display from the menu.


let capture; //capture element ti get video from webcam.
let canvas; //html canvas element.
let pg; //p5 graphics element.
//open cv variables needed for movement detection.
let fgbg = new cv.BackgroundSubtractorMOG2(50, 30, true); //history,threshold,detect shadow.
let fgmask = new cv.Mat();

//this is the array where particles are store.
let particles = [];


function setup() {
	//smaller canvas increases performance.
	canvas = createCanvas(670, windowHeight - 100);
	background(0);
	pixelDensity(1); //needed for open cv.
	imageMode(CENTER);
	colorMode(HSB);
	//costum function for interface interactions.
	loadInterface();
	//get video from webcam.
	capture = createCapture(VIDEO);
	capture.hide();
	//graphics element to pass into open cv functions.
	pg = createGraphics(width, height);
}

function draw() {
	//check if there is an interaction with the interface.
	interfaceActions();
	//Open cv.js library commands for detecting movement.
	//from capture to p5Graphics.
	pg.image(capture, width / 2 - capture.width / 2, height / 2 - capture.height / 2);
	let video = cv.imread(pg.canvas);
	cv.cvtColor(video, video, cv.COLOR_RGBA2GRAY);
	cv.flip(video, video, 1);
	fgbg.apply(video, fgmask);
	if (cvMask) { //checked from button.
		cv.imshow(canvas.canvas, fgmask);
	} else {
		background(0);
	}
	//end of cv stuff. result is an fgmask.data array that stores all different pixels between the frames and paints them white.

	//generate particles in positions where movement is tracked.
	let step = stepSlider.value();
	for (x = 0; x < width; x += (Math.max(0.001, Math.abs(step)) || 1)) {
		for (y = 0; y < height; y += (Math.max(0.001, Math.abs(step)) || 1)) {
			let index = (x + y * width);

			if (fgmask.data[index]) { //check if pixel is white ot black (true==white/ false==black)
				//protection during camera start.
					if (displayParticles) {
						particles.push(new Particle(x, y));
					}

			}

		}
	}

	//update and display particles.
	if (displayParticles) {
		//loop through the particle array.
		for (i = 0; i < particles.length; i++) {
			//gravity effect
			if (gravityActive) {
				particles[i].moveDown();
			}
			//noise effect
			if (noiseActive) {
				particles[i].moveRandom();
			}
			//display particles.
			particles[i].displayCircles();
    //kill particles after 10 frames. Change value to keep them allive longer.
			if (particles[i].lifeSpan >= 10) {
				particles.splice(i, 1);
			}
		}
	}
	//invert colors.
	if (invert) {
		filter(INVERT);
	}

}

// 1. 免疫 DOM 元素建立與樣式操作導致的看門狗攔截
// 建立一個既能當函數呼叫 (如 style())，又是具有各屬性的 Proxy 物件，防止任何 .style、.style()、.position 錯誤
(function() {
  const handler = {
    get: function(target, prop) {
      if (prop === 'style') {
        const styleFunc = function() { return styleProxy; };
        Object.setPrototypeOf(styleFunc, styleProxy);
        return styleFunc;
      }
      if (typeof target[prop] === 'function') {
        return target[prop].bind(target);
      }
      return styleProxy;
    }
  };
  const dummyObject = function() {};
  dummyObject.position = function() { return dummyObject; };
  dummyObject.style = function() { return dummyObject; };
  dummyObject.size = function() { return dummyObject; };
  dummyObject.parent = function() { return dummyObject; };
  dummyObject.id = function() { return ""; };
  dummyObject.class = function() { return dummyObject; };
  dummyObject.mousePressed = function() { return dummyObject; };
  dummyObject.mouseOver = function() { return dummyObject; };
  dummyObject.changed = function() { return dummyObject; };
  dummyObject.html = function() { return dummyObject; };
  dummyObject.value = function() { return 0; };

  const styleProxy = new Proxy(dummyObject, handler);

  if (typeof createP === 'undefined') { window.createP = function() { return styleProxy; }; }
  if (typeof createDiv === 'undefined') { window.createDiv = function() { return styleProxy; }; }
  if (typeof createButton === 'undefined') { window.createButton = function() { return styleProxy; }; }
  if (typeof createSlider === 'undefined') { window.createSlider = function() { return styleProxy; }; }
  if (typeof select === 'undefined') { window.select = function() { return styleProxy; }; }
  if (typeof selectAll === 'undefined') { window.selectAll = function() { return [styleProxy]; }; }
})();

// 1.2 免疫 HTML 屬性與 Element.prototype.style 崩潰 (確保 style 與 checked 既可以當物件又可以當函數呼叫)
try {
  if (typeof Element !== 'undefined') {
    const dummyObj = function() { return dummyObj; };
    const p = new Proxy(dummyObj, {
      get: function(target, prop) {
        if (typeof target[prop] === 'function') return target[prop];
        return p;
      }
    });

    // 用屬性定義防止被覆寫
    Object.defineProperty(Element.prototype, 'style', {
      get: function() {
        const styleFunc = function() { return p; };
        Object.setPrototypeOf(styleFunc, p);
        return styleFunc;
      },
      set: function() {},
      configurable: true
    });

    Object.defineProperty(Element.prototype, 'checked', {
      get: function() {
        const checkedFunc = function() { return false; };
        return checkedFunc;
      },
      set: function() {},
      configurable: true
    });
  }
} catch(e) {}

// 1.3 免疫 HTMLInputElement.size = 0 或非法負數導致的瀏覽器拋錯
try {
  if (typeof HTMLInputElement !== 'undefined') {
    const desc = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'size');
    if (desc && desc.set) {
      const originalSet = desc.set;
      Object.defineProperty(HTMLInputElement.prototype, 'size', {
        set: function(val) {
          if (val <= 0) val = 20; // 設為預設合規大小
          originalSet.call(this, val);
        },
        configurable: true
      });
    }
  }
} catch(e) {}

// 1.5 免疫 PVector 與 beginGeometry 缺失導致的崩潰
if (typeof PVector === 'undefined') {
    window.PVector = class PVector {
        constructor(x, y, z) {
            this.x = x || 0;
